	}{
		{"white mates", "7k/6Q1/5K2/8/8/8/8/8 b - - 0 1", mateScore},
		{"black mates", "8/8/8/8/8/5k2/6q1/7K w - - 0 1", -mateScore},
		{"black stalemated", "7k/5K2/6Q1/8/8/8/8/8 b - - 0 1", 0},
		{"white stalemated", "8/8/8/8/8/6q1/5k2/7K w - - 0 1", 0},
